const PEOPLE_ROWS_BY_ID = Object.fromEntries(
  PEOPLE_ROWS.map((row) => [row.id, row])
);

function getPeopleRows(filters = {}) {
  return PEOPLE_ROWS.filter((row) => {
    if (filters.population && row.population !== filters.population) return false;
    if (filters.measure && row.measure !== filters.measure) return false;
    if (filters.academicYear && row.academicYear !== filters.academicYear) return false;
    if (filters.startYear && row.startYear !== filters.startYear) return false;
    if (filters.categoryType && row.categoryType !== filters.categoryType) return false;
    if (filters.category && row.category !== filters.category) return false;
    return true;
  });
}

function getPeopleTotal(population, academicYear, measure) {
  return PEOPLE_TOTALS.find((row) =>
    row.population === population &&
    row.academicYear === academicYear &&
    row.measure === measure
  ) || null;
}

function getPeopleCategories(population, categoryType, measure, academicYear) {
  return getPeopleRows({
    population,
    categoryType,
    measure,
    academicYear
  });
}
